import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, Color, Vector3, PointLight } from "three/webgpu";
import { texture, uv, normalMap, displacementMap, replace, mul, div, mix, float, vec2 } from "three/tsl";
import { gsap } from "gsap";
import { parallaxScroll, depthRotate } from "@/primitives";

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {string} [depthMapUrl]
 * @property {Array<{name:string,params:any,trigger:string}>} [cinematicPrimitives]
 * @property {Array<{event:string,effect:string}>} [interactions]
 * @property {Object} [visualSpec]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{loadTexture(url:string):Promise<any>}} textureLoader
 * @property {{emit(event:string, payload:any):void}} emit
 * @property {{[key:string]:(target:any,params:any)=>{timeline:any,cleanup:()=>void}}} primitives
 * @property {{createText(content:string,opts?:any):any}} fontAtlas
 */

/**
 * Create a parallax quote panel node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const root = new Group();
  root.name = "quote-panel";

  // ---- Geometry & Material ----
  const geometry = new PlaneGeometry(7, 6, 64, 64); // size matches backdrop spec, will be scaled later
  const material = new MeshStandardNodeMaterial();
  material.colorNode = replace(
    texture(uv()),
    ctx.THREE.Texture.DEFAULT_IMAGE,
    new Color(config.visualSpec?.colors?.paper ?? "#e8ecf2")
  );

  // Placeholder texture nodes – will be replaced once loaded
  const mapNode = texture(uv());
  const dispNode = displacementMap(uv());

  material.mapNode = mapNode;
  material.displacementNode = dispNode;
  material.roughness = 0.8;
  material.metalness = 0.1;

  const mesh = new Mesh(geometry, material);
  mesh.name = "panel-mesh";
  root.add(mesh);

  // ---- Load Textures (async, applied later) ----
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.mapNode = texture(uv(), { map: tex });
      material.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      material.displacementNode = displacementMap(uv(), { map: tex, scale: 0.2 });
      material.needsUpdate = true;
    });
  }

  // ---- Accent Rim Light (simple point light) ----
  const rimLight = new PointLight("#ff2a38", 0.6, 5);
  rimLight.position.set(0, 0, 0.5);
  root.add(rimLight);

  // ---- Apply Cinematic Primitives ----
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params);
        primitiveInstances.push(instance);
      }
    }
  }

  // ---- Interaction Handlers ----
  root.userData.handlers = {};

  // Hover rise-in preset (subtle 0.15 units)
  const hoverEffect = () => {
    const tl = gsap.timeline({ defaults: { ease: "power3.out", duration: 0.7 } });
    tl.to(
      root.position,
      { y: `+=${0.15}`, ease: "power3.out", duration: 0.7 }
    );
    return tl;
  };

  // Store timeline to kill on cleanup
  let hoverTimeline = null;

  root.userData.handlers.hover = (enter) => {
    if (enter) {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = hoverEffect();
    } else {
      if (hoverTimeline) {
        hoverTimeline.reverse();
        hoverTimeline = null;
      }
    }
  };

  // Click emit
  root.userData.handlers.click = () => {
    ctx.emit("hub-home.select", {});
  };

  // Register any extra interactions from config
  if (Array.isArray(config.interactions)) {
    for (const int of config.interactions) {
      if (int.event === "hover") {
        root.userData.handlers.hover = (enter) => {
          if (enter) hoverEffect();
        };
      }
      if (int.event === "click") {
        root.userData.handlers.click = () => {
          ctx.emit(int.effect.split(":")[1] ?? "unknown", {});
        };
      }
    }
  }

  // ---- Cleanup ----
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Cancel any GSAP timelines
    if (hoverTimeline) hoverTimeline.kill();

    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === "function") inst.cleanup();
    }
  };

  return root;
}
